	root.SetHelpCommand(&cobra.Command{Use: "no-help", Hidden: true, Run: func(cmd *cobra.Command, args []string) {}})

	// Custom help function
	root.SetHelpFunc(func(cmd *cobra.Command, args []string) {
		// Print hardcoded help based on command
		printHelp(cmd)
