	pf.BoolVarP(&flagFollowAll, "follow-all", "A", false, "follow multiple files and show the most recently updated one")
	pf.BoolVarP(&flagFollowMode, "follow-mode", "f", false, "monitor file and display new content as it is written")
	pf.BoolVar(&flagFollowName, "follow-name", false, "follow mode to monitor by file name")
	pf.BoolVar(&flagFollowSection, "follow-section", false, "section-by-section follow mode")
	pf.BoolVar(&flagForceScreen, "force-screen", false, "display screen even when redirecting output")
	pf.IntVarP(&flagHeader, "header", "H", 0, "number of header lines to be displayed constantly")
	pf.IntVarP(&flagHeaderColumn, "header-column", "Y", 0, "number of columns to display as a vertical header")
	pf.BoolVar(&flagHelpKey, "help-key", false, "display key bind information")
	pf.BoolVar(&flagHideOtherSection, "hide-other-section", false, "hide other section")
	pf.StringVar(&flagHscrollWidth, "hscroll-width", "10%", "width to scroll horizontally [int|int%|.int]")
	pf.BoolVar(&flagIncsearch, "incsearch", true, "incremental search")
