		for _, sub2 := range sub.Commands() {
			sub2.SetHelpFunc(func(cmd *cobra.Command, args []string) {
				printHelp(cmd)
			})
		}
		// Silence errors/usage for subcommands too?
		sub.SilenceErrors = true
		sub.SilenceUsage = true
		for _, sub2 := range sub.Commands() {
			sub2.SilenceErrors = true
			sub2.SilenceUsage = true
		}
	}

	// Handle flag error func to match ov: print "Error: ..." without usage
	root.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return err
	})
	// Also for subcommands?
	for _, sub := range root.Commands() {
		sub.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return err
		})
		for _, sub2 := range sub.Commands() {
			sub2.SetFlagErrorFunc(func(cmd *cobra.Command, args []string) error {
				_ = args
				return nil
			})
			// Actually need same signature
			_ = sub2
		}
	}
	// Fix sub2 flag error func correctly
	for _, sub := range root.Commands() {
		for _, sub2 := range sub.Commands() {
			c := sub2
			c.SetFlagErrorFunc(func(cmd *cobra.Command, err error) error {
				fmt.Fprintf(os.Stderr, "Error: %v\n", err)
				_ = c
				return err
			})
		}
	}

	return root
}

func registerCompletions(root *cobra.Command) {
	// column-delimiter
	root.RegisterFlagCompletionFunc("column-delimiter", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{",\tcomma", "|\tvertical line", "\\t\ttab", "─\tbox"}, cobra.ShellCompDirectiveNoFileComp
	})
	// completion
	root.RegisterFlagCompletionFunc("completion", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"bash", "zsh", "fish", "powershell"}, cobra.ShellCompDirectiveNoFileComp
	})
	// config - file extension yaml
	root.MarkFlagFilenameExtension("config", "yaml")
	// converter
	root.RegisterFlagCompletionFunc("converter", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"es\tEscape Sequence", "raw\tRaw output of escape sequences", "align\tAlign Column Widths"}, cobra.ShellCompDirectiveNoFileComp
	})
	// header
	root.RegisterFlagCompletionFunc("header", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"1"}, cobra.ShellCompDirectiveNoFileComp
	})
	// header-column
	root.RegisterFlagCompletionFunc("header-column", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"1"}, cobra.ShellCompDirectiveNoFileComp
	})
	// ruler - empty with Default (to match :0)
	root.RegisterFlagCompletionFunc("ruler", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return nil, cobra.ShellCompDirectiveDefault
	})
	// skip-lines
	root.RegisterFlagCompletionFunc("skip-lines", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"1"}, cobra.ShellCompDirectiveNoFileComp
	})
	// tab-width
	root.RegisterFlagCompletionFunc("tab-width", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"3\ttab width", "2\ttab width", "4\ttab width", "8\ttab width"}, cobra.ShellCompDirectiveNoFileComp
	})
	// vertical-header
	root.RegisterFlagCompletionFunc("vertical-header", func(cmd *cobra.Command, args []string, toComplete string) ([]string, cobra.ShellCompDirective) {
		return []string{"1"}, cobra.ShellCompDirectiveNoFileComp
	})
}

func printHelp(cmd *cobra.Command) {
	// Determine which help to print based on command path
	path := cmd.CommandPath() // e.g., "ov", "ov completion", "ov completion bash"
	var data []byte
	var err error
	switch path {
	case "ov":
		data, err = helpFS.ReadFile("helpdata/root_help.txt")
	case "ov completion":
		data, err = helpFS.ReadFile("helpdata/completion_help.txt")
	case "ov completion bash":
		data, err = helpFS.ReadFile("helpdata/completion_bash_help.txt")
	case "ov completion zsh":
		data, err = helpFS.ReadFile("helpdata/completion_zsh_help.txt")
	case "ov completion fish":
		data, err = helpFS.ReadFile("helpdata/completion_fish_help.txt")
	case "ov completion powershell":
		data, err = helpFS.ReadFile("helpdata/completion_powershell_help.txt")
	default:
		// Fallback to root help?
		data, err = helpFS.ReadFile("helpdata/root_help.txt")
