{"command":"cat > config.go <<'GO'
package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/BurntSushi/toml"
	"gopkg.in/yaml.v3"
)

var supportedExts = map[string]bool{
	"yaml": true, "yml": true, "json": true, "toml": true,
	"ini": true, "hcl": true, "tfvars": true,
	"prop": true, "props": true, "properties": true,
	"env": true, "dotenv": true,
}

var searchOrder = []string{"json","toml","yaml","yml","properties","props","prop","hcl","tfvars","dotenv","env","ini"}

type Config struct {
	DefaultKeyBind string
	KeyBind map[string][]string
	Mode map[string]interface{}
	Raw map[string]interface{}
}

func newDefaultConfig() *Config {
	return &Config{
		KeyBind: map[string][]string{},
		Mode: map[string]interface{}{},
		Raw: map[string]interface{}{},
	}
}

// loadConfig returns config, stderr messages to print (failed..., Using..., etc.), and whether to proceed (always true except?)
// flagConfig is --config value, debug is --debug
func loadConfig(flagConfig string, debug bool) (*Config, string) {
	cfg := newDefaultConfig()
	var stderr strings.Builder

	if flagConfig != "" {
		// Explicit config
		ext := configExt(flagConfig)
		if !supportedExts[ext] {
			stderr.WriteString(fmt.Sprintf("failed to read config file: Unsupported Config Type %q\n", ext))
			if debug {
				stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
			}
			return cfg, stderr.String()
		}
		// Try open and read
		f, err := os.Open(flagConfig)
		if err != nil {
			stderr.WriteString(fmt.Sprintf("failed to read config file: %v\n", err))
			if debug {
				stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
			}
			return cfg, stderr.String()
		}
		data, err := readAllFile(f, flagConfig)
		f.Close()
		if err != nil {
			stderr.WriteString(fmt.Sprintf("failed to read config file: %v\n", err))
			if debug {
				stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
			}
			return cfg, stderr.String()
		}
		// Parse based on ext
		if ext == "ini" || ext == "hcl" || ext == "tfvars" || ext == "prop" || ext == "props" || ext == "properties" {
			stderr.WriteString("failed to read config file: While parsing config: decoder not found for this format\n")
			if debug {
				stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
			}
			return cfg, stderr.String()
		}
		if ext == "env" || ext == "dotenv" {
			// Parse dotenv: check each line
			if err := parseDotenv(data); err != nil {
				stderr.WriteString(fmt.Sprintf("failed to read config file: While parsing config: %v\n", err))
				if debug {
					stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
				}
				return cfg, stderr.String()
			}
			// Success, no Mode/KeyBind from env (ignore)
			if debug {
				stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
			}
			return cfg, stderr.String()
		}
		// yaml, yml, json, toml
		parsed, err := parseConfigData(data, ext)
		if err != nil {
			stderr.WriteString(fmt.Sprintf("failed to read config file: While parsing config: %v\n", err))
			if debug {
				stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
			}
			return cfg, stderr.String()
		}
		applyParsed(cfg, parsed)
		if debug {
			stderr.WriteString(fmt.Sprintf("Using config file: %s\n", flagConfig))
		}
		return cfg, stderr.String()
	}
	// Default search
	searchPath, homeErr := defaultSearchPath()
	if homeErr != "" {
		// $HOME is not defined
		stderr.WriteString(homeErr + "\n")
		return cfg, stderr.String()
	}
	// Search for config files in order
	var foundPath string
	var foundExt string
	for _, ext := range searchOrder {
		p := filepath.Join(searchPath, "config."+ext)
		info, err := os.Stat(p)
		if err != nil {
			continue
		}
		if info.IsDir() {
			continue
		}
		foundPath = p
		foundExt = ext
		break
	}
	if foundPath == "" {
		// Not found
		if debug {
			stderr.WriteString(fmt.Sprintf("failed to read config file: Config File \"config\" Not Found in \"[%s]\"\n", searchPath))
			stderr.WriteString("config file not found\n")
		}
		return cfg, stderr.String()
	}
	// Found, try to read and parse (similar to explicit, but Using path is absolute foundPath)
	// For default, foundPath is already absolute (since searchPath is absolute)
	f, err := os.Open(foundPath)
	if err != nil {
		// Should not happen since Stat succeeded, but handle
		stderr.WriteString(fmt.Sprintf("failed to read config file: %v\n", err))
		if debug {
			stderr.WriteString(fmt.Sprintf("Using config file: %s\n", foundPath))
		}
		return cfg, stderr.String()
	}
	data, err := readAllFile(f, foundPath)
	f.Close()
	if err != nil {
		stderr.WriteString(fmt.Sprintf("failed to read config file: %v\n", err))
		if debug {
			stderr.WriteString(fmt.Sprintf("Using config file: %s\n", foundPath))
		}
		return cfg, stderr.String()
	}
	if foundExt == "ini" || foundExt == "hcl" || foundExt == "tfvars" || foundExt == "prop" || foundExt == "props" || foundExt == "properties" {
		stderr.WriteString("failed to read config file: While parsing config: decoder not found for this format\n")
		if debug {
			stderr.WriteString(fmt.Sprintf("Using config file: %s\n", foundPath))
		}
		return cfg, stderr.String()
	}
	if foundExt == "env" || foundExt == "dotenv" {
		if err := parseDotenv(data); err != nil {
			stderr.WriteString(fmt.Sprintf("failed to read config file: While parsing config: %v\n", err))
			if debug {
				stderr.WriteString(fmt.Sprintf("Using config file: %s\n", foundPath))
			}
			return cfg, stderr.String()
		}
		if debug {
			stderr.WriteString(fmt.Sprintf("Using config file: %s\n", foundPath))
		}
