	if cfg.DefaultKeyBind == "disable" {
		// Start empty
		for _, e := range helpOrder {
			effective[e.Action] = []string{}
		}
		// Apply config
		for action, keys := range cfg.KeyBind {
			// Only for known actions? Unknown actions don't affect display (but affect duplicates/invalid? For invalid, unknown actions with invalid keys should still be reported? Let's see: unknown action with invalid key - does it report invalid? Test: invalid_action with invalid key?
