		}
	} else {
		// Start with defaults
		for k, v := range defaultKeys {
			effective[k] = append([]string{}, v...)
		}
		// Apply config overrides
		for action, keys := range cfg.KeyBind {
			if _, ok := isKnownAction(action); ok {
				// Override (even if empty list? Empty list means [] (clear). Null means keep defaults (but null not in map, so not override). Good.
				effective[action] = append([]string{}, keys...)
			}
		}
	}
	// Generate categories
	currentCat := ""
	for _, e := range helpOrder {
		if e.Category != currentCat {
			if currentCat != "" {
				b.WriteString("\n")
			}
			b.WriteString("\t" + e.Category + "\n")
			currentCat = e.Category
		}
		keys := effective[e.Action]
		var keyStr string
		if len(keys) == 0 {
			keyStr = "[]"
		} else {
			parts := make([]string, len(keys))
			for i, k := range keys {
				parts[i] = "[" + k + "]"
			}
			keyStr = strings.Join(parts, ", ")
		}
		// Format: " " + keyStr padded to 32 (including leading space) + "* " + desc
		// Leading space + keyStr
		linePrefix := " " + keyStr
		// Pad to 32? Actually "*" at column 32 (0-indexed)? Let's compute: linePrefix length, pad with spaces to 32, then "* " + desc
