	}
	b.WriteString("\n")

	// Check invalid and duplicate
	// Collect all KeyBind entries for validation (including unknown? For invalid, need to check all, including unknown? Let's test unknown invalid.)
	// For effective display we only used known, but for validation we need all config entries plus defaults? Or only effective?
