	// For known with disable, effective is config or empty. For known with defaults, effective is defaults overridden.
	// Actually duplicates should be checked on effective keys (after merge), not just config? Example: with default (not disable), if config sets exit to "H" (which is header's default), then exit and header would duplicate. That should be reported. So check effective.
	// For unknown actions, effective is config value (since no default). They participate.
	// For invalid: check effective keys for all actions (known + unknown config)? Or only config? Example: defaults are all valid, so invalid only comes from config. But if config overrides with invalid, effective will contain invalid, so check effective. Good.
	// Build map for validation: action -> keys (effective for known, config for unknown)
	validationMap := map[string][]string{}
	for k, v := range effective {
		validationMap[k] = v
	}
	// Add unknown config entries
	for action, keys := range cfg.KeyBind {
		if _, ok := isKnownAction(action); !ok {
			validationMap[action] = keys
		}
	}

	invalids := []string{} // each is "Error: invalid key format: key <key> for action <action>"
	for action, keys := range validationMap {
