	}
	if len(dups) > 0 {
		b.WriteString("\n\tDuplicate key bindings:\n")
		for _, d := range dups {
			b.WriteString(fmt.Sprintf("Duplicate key [%s] for %s\n", d.Key, strings.Join(d.Actions, ", ")))
		}
	}
	return b.String()
