func isKnownAction(action string) (bool, bool) {
	for _, e := range helpOrder {
		if e.Action == action {
			return true, true
		}
	}
	return false, false
}

func isValidKey(k string) bool {
	if k == "" {
		return false
	}
	// Single char: valid (any single rune? Including symbols? Assume yes, except maybe? Test showed all single chars valid, including "!" etc.)
	// Need to handle rune length, not byte length? For unicode single char like "─"? Probably valid? But keys are ascii? Assume any single rune valid.
	runes := []rune(k)
	if len(runes) == 1 {
		// Single char always valid? What about control? Assume valid.
		return true
	}
	// Check if contains "+"
	if strings.Contains(k, "+") {
		parts := strings.Split(k, "+")
		// Last part must be valid key (single char or named), preceding parts must be modifiers or valid? Simplify: last part must be single char or valid named, preceding must be modifiers (ctrl, alt, shift, meta, case-insensitive)
		// Handle empty parts? For "a++" (parts ["a","",""]), last part "" invalid, but real says valid. So our simplified will say invalid, differing. But unlikely tested.
		// For "++a" (parts ["","","a"]), preceding include empty, real says valid. Our simplified would say invalid (empty not modifier). Differ.
		// To match common cases, require preceding non-empty parts to be modifiers, and last part to be single char or named.
		// For empty parts (due to "++"), treat "+" as key? Actually "a++" could be interpreted as "a" + "+" (where "+" is key)? The string "a++" has two "+" separators, last part "" (empty), but second last is ""? Hmm.
		// Simplify: if any part is empty (due to consecutive "+" or trailing "+"), then invalid, except for cases where "+" itself is key? But "+" as key would be single char "+", e.g., "ctrl++" (modifier + "+" key)? That would be parts ["ctrl","",""]? Last part "" invalid, but real might consider "ctrl++" valid? We haven't tested "ctrl++" (ctrl + "+" key). Let's assume invalid for now.
		// Check last part
		last := parts[len(parts)-1]
		if last == "" {
			return false
		}
		// Last must be single char (len 1) or valid named (case-insensitive, F1-F64, etc.)
		if len([]rune(last)) != 1 && !isNamedKey(last) {
			return false
		}
		// Preceding parts must be modifiers (case-insensitive ctrl, alt, shift, meta)
		for _, p := range parts[:len(parts)-1] {
			if p == "" {
				return false
			}
			lower := strings.ToLower(p)
			if lower != "ctrl" && lower != "alt" && lower != "shift" && lower != "meta" {
				return false
			}
		}
		return true
	}
	// No "+", must be named key (case-insensitive)
	return isNamedKey(k)
}

func isNamedKey(s string) bool {
	lower := strings.ToLower(s)
	// List of valid named keys (lowercased)
	valid := map[string]bool{
		"enter": true, "backspace": true, "tab": true, "backtab": true,
		"esc": true, "escape": true, "delete": true, "insert": true,
		"up": true, "down": true, "left": true, "right": true,
		"home": true, "end": true, "pageup": true, "pagedown": true,
		"pgup": true, "pgdn": true, "space": true, "cancel": true,
		"clear": true, "pause": true, "print": true,
	}
	if valid[lower] {
		return true
	}
	// F1-F64 (case-insensitive F)
	if len(s) >= 2 && (s[0] == 'F' || s[0] == 'f') {
		numStr := s[1:]
		// Check all digits
		for _, c := range numStr {
			if c < '0' || c > '9' {
				return false
			}
		}
		// Parse number
		n := 0
		for _, c := range numStr {
			n = n*10 + int(c-'0')
		}
		if n >= 1 && n <= 64 {
			return true
		}
		return false
	}
	return false
}
