	case "ov completion powershell":
		data, err = helpFS.ReadFile("helpdata/completion_powershell_help.txt")
	default:
		data, err = helpFS.ReadFile("helpdata/root_help.txt")
	}
	if err != nil {
		fmt.Fprintf(os.Stdout, "help error: %v\n", err)
		return
	}
	fmt.Fprint(os.Stdout, string(data))
}

func runRoot(cmd *cobra.Command, args []string) error {
	// Precedence: version > help-key > list-view-modes > completion > normal
	// Help is handled by cobra before RunE, so no need to handle here.
	// But need to load config for all except help (help already handled, so here we always load config)
	cfg, configStderr := loadConfig(flagConfig, flagDebug)
	// Helper to print config stderr first
	printConfigStderr := func() {
		if configStderr != "" {
			fmt.Fprint(os.Stderr, configStderr)
		}
	}

	// Version
	if flagVersion {
		printConfigStderr()
		fmt.Fprint(os.Stdout, "ov version dev rev:HEAD\n")
		return nil
	}
	// Help-key
	if flagHelpKey {
		printConfigStderr()
		out := generateHelpKey(cfg)
		fmt.Fprint(os.Stdout, out)
		return nil
	}
	// List-view-modes
	if flagListViewModes {
		printConfigStderr()
		modes := listViewModes(cfg)
		for _, m := range modes {
			fmt.Fprintln(os.Stdout, m)
		}
		return nil
	}
	// Completion flag
	if cmd.Flags().Changed("completion") {
		printConfigStderr()
		val := flagCompletion
		var buf bytes.Buffer
		var err error
		switch val {
		case "bash":
			err = cmd.Root().GenBashCompletion(&buf)
		case "zsh":
			err = cmd.Root().GenZshCompletion(&buf)
		case "fish":
			err = cmd.Root().GenFishCompletion(&buf, true)
		case "powershell":
			err = cmd.Root().GenPowerShellCompletion(&buf)
		default:
			fmt.Fprint(os.Stderr, "Error: requires one of the arguments bash/zsh/fish/powershell\n")
			return fmt.Errorf("requires one of the arguments bash/zsh/fish/powershell")
		}
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return err
		}
		fmt.Fprint(os.Stdout, buf.String())
		return nil
	}

	// Normal file handling
	return runPager(cmd, args, cfg, configStderr)
}

func runPager(cmd *cobra.Command, args []string, cfg *Config, configStderr string) error {
	// Check if completion subcommand? No, this is root RunE, completion subcommands have their own Run (cobra default). So args here are files.
	// Determine if stdout is tty or force-screen
	// For now, implement piped vs TUI decision
	isForce := flagForceScreen
	isTTY := isStdoutTTY()
	if !isForce && !isTTY {
		// Piped mode: print config stderr first (if any), then cat
		if configStderr != "" {
			fmt.Fprint(os.Stderr, configStderr)
		}
		return runPiped(args)
	}
	// TUI mode (stdout is tty or force-screen)
	// For TUI, config stderr should be printed? When stdout is tty, config errors go to stderr (terminal). But TUI will take over screen. How does ov handle config errors in TUI mode?
	// When TUI is launched, config errors are probably shown in log or ignored? Let's test: with tty, --config nonexistent.yaml + file, does it show TUI or error?
	// We haven't tested TUI with bad config. Let's assume for TUI, config errors are printed to stderr before launching TUI? Or maybe they are shown after quit?
	// For force-screen with piped stdout and bad config, it printed config error + missing file/Screen error. So for TUI errors (missing file, etc.), config error comes first.
	// For successful TUI launch, config errors (like failed to read) might be printed to stderr but TUI still launches (stderr goes to terminal, but TUI uses alternate screen?).
	// Simplify: if configStderr != "", print to stderr before TUI? But when TUI uses alternate screen, stderr might be hidden. However, our earlier test with TUI and bad config? We haven't tested. Let's implement: print config stderr to stderr before TUI launch (it will appear on terminal, then TUI takes over?).
	// Actually, for TUI with bad config, the config error should probably be shown after TUI? Hmm.
	// Let's first implement TUI error handling for missing file etc., with config stderr.
	return runTUI(args, cfg, configStderr)
}

func runPiped(args []string) error {
	if len(args) == 0 {
		// Copy stdin to stdout
		_, err := io.Copy(os.Stdout, os.Stdin)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: %v\n", err)
			return err
		}
		return nil
	}
	// Only first file
	fname := args[0]
	f, err := os.Open(fname)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return err
	}
	defer f.Close()
	_, err = io.Copy(os.Stdout, f)
	if err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		return err
	}
	return nil
}
GO
"}

