			// ".int" e.g., ".5" -> 0.5
			f, err := strconv.ParseFloat("0"+numStr, 64)
			if err != nil {
				return termWidth / 10
			}
			return int(float64(termWidth) * f)
		}
		// "int%" e.g., "10%" -> 10% of width
		n, err := strconv.Atoi(numStr)
		if err != nil {
			return termWidth / 10
		}
		return termWidth * n / 100
